mapper.select:
SELECT c.cr_year, c.cr_fuel_type, c.cr_trans, ct.ct_key, ct.ct_name, ct.ct_type, ct.ct_thumbnail, MIN(c.cr_price) AS cr_price FROM car c JOIN car_type ct ON c.ct_key = ct.ct_key
AND ct.ct_type IN
#{type}
AND ct.ct_name LIKE CONCAT('%', #{cri.ct_name}, '%')
AND c.cr_fuel_type IN
#{fuel}
AND c.cr_trans IN
#{gear}
AND c.cr_price <= #{cri.price}
GROUP BY c.cr_year, c.cr_fuel_type, c.cr_trans, ct.ct_key, ct.ct_name, ct.ct_type, ct.ct_thumbnail
ORDER BY cr_price ASC
ORDER BY c.cr_year DESC
ORDER BY ct.ct_key DESC
